css.content:
/* ─── Loading: a spinner that steps, and a still skeleton ─── */
.spinner { width: 16px; height: 16px; display: inline-block; border: 2px solid var(--rule); border-top-color: var(--foreground); border-radius: var(--round); animation: spin 0.8s steps(8) infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.skeleton { display: block; height: 1em; background: var(--wash-2); }
.skeleton-block { height: var(--s8); }
.skeleton-hatch { background: var(--hatch); box-shadow: inset 0 0 0 1px var(--rule); }

source.content:
import {forwardRef, type HTMLAttributes} from 'react';
import {cx} from '../../utils/cx';

export interface SpinnerProps extends HTMLAttributes<HTMLSpanElement> {
  /** What is loading, read by screen readers. */
  label?: string;
}

/** A small stepped spinner. It stops under reduced motion (base styles). */
export const Spinner = forwardRef<HTMLSpanElement, SpinnerProps>(function Spinner({label = 'Loading', className, ...rest}, ref) {
  return <span ref={ref} role="status" aria-label={label} className={cx('spinner', className)} {...rest} />;
});
